package com.lamontlabs.quantravision.next.engine;

import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.concurrent.atomic.AtomicInteger;

/** The same deterministic regressions run locally and through JUnit in GitHub Actions. */
public final class EngineChecks {
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private static ChartEngine.Result sample(boolean light,boolean neutral){return new ChartEngine().analyze(SamplePixels.WIDTH,SamplePixels.HEIGHT,SamplePixels.create(light,neutral));}
    private static boolean has(List<ChartEngine.Match> matches,String kind){for(ChartEngine.Match m:matches)if(m.id.startsWith(kind+"_"))return true;return false;}
    public static void darkChart(){ChartEngine.Result r=sample(false,false);check(r.readable(),r.problem);check(r.candles.size()==44,"Expected 44 measured candles");check(has(r.matches,"double_top"),"Missing double top");}
    public static void lightChart(){ChartEngine.Result r=sample(true,false);check(r.readable(),r.problem);check(r.candles.size()==44,"Light chart lost candles");check(has(r.matches,"double_top"),"Missing light-chart double top");}
    public static void darkNeutralWicks(){ChartEngine.Result r=sample(false,true);check(r.candles.size()==44,"Gray wicks were not recovered");check(has(r.matches,"double_top"),"Gray-wick chart structure lost");}
    public static void lightNeutralWicks(){ChartEngine.Result r=sample(true,true);check(r.candles.size()==44,"Light gray wicks lost");check(has(r.matches,"double_top"),"Missing gray-wick double top");}
    public static void blankRejected(){int[] p=new int[480*320];Arrays.fill(p,0xff101820);ChartEngine.Result r=new ChartEngine().analyze(480,320,p);check(!r.readable()&&r.candles.isEmpty()&&r.matches.isEmpty(),"Blank image produced observations");}
    public static void tooSmallRejected(){ChartEngine.Result r=new ChartEngine().analyze(100,80,new int[8000]);check(!r.readable()&&r.problem.contains("small"),"Small image must explain rejection");}
    public static void badDimensions(){boolean rejected=false;try{new ChartEngine().analyze(Integer.MAX_VALUE,2,new int[0]);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"Dimension overflow accepted");}
    public static void transparentRejected(){int[] p=SamplePixels.create(false,false);for(int i=0;i<p.length;i++)p[i]&=0xffffff;check(!new ChartEngine().analyze(SamplePixels.WIDTH,SamplePixels.HEIGHT,p).readable(),"Transparent colors accepted");}
    public static void unsupportedPalette(){int[] p=SamplePixels.create(false,false);for(int i=0;i<p.length;i++)if(p[i]==0xff42ddb2||p[i]==0xffef7d85)p[i]=0xff7180ed;check(!new ChartEngine().analyze(SamplePixels.WIDTH,SamplePixels.HEIGHT,p).readable(),"Blue series must not silently become red/green data");}
    public static void noiseRejected(){Random random=new Random(8411);for(int f=0;f<8;f++){int[] p=new int[480*320];for(int i=0;i<p.length;i++)p[i]=0xff000000|random.nextInt(0x1000000);check(!new ChartEngine().analyze(480,320,p).readable(),"Noise fixture "+f+" passed");}}
    public static void volumeRejected(){int[] p=new int[SamplePixels.WIDTH*SamplePixels.HEIGHT];Arrays.fill(p,0xff0d1728);for(int i=0;i<40;i++)SamplePixels.rect(p,60+i*20,350-(i%9)*17,70+i*20,480,i%2==0?0xff42ddb2:0xffef7d85);check(!new ChartEngine().analyze(SamplePixels.WIDTH,SamplePixels.HEIGHT,p).readable(),"Volume bars mistaken for candles");}
    public static void measuredBodies(){ChartEngine.Candle c=sample(false,false).candles.get(0);check(c.left==60&&c.right==70,"Body x coordinates invented");check(c.bodyTop==385&&c.bodyBottom==393,"Open/close body range changed: "+c.bodyTop+".."+c.bodyBottom);check(c.top==375&&c.bottom==403,"Wick bounds not measured: "+c.top+".."+c.bottom);}
    public static void boundsRemainInImage(){ChartEngine.Result r=sample(false,false);for(ChartEngine.Candle c:r.candles)check(c.left>=0&&c.right<=r.width&&c.top>=0&&c.bottom<=r.height,"Candle outside image");for(ChartEngine.Match m:r.matches){check(m.left>=0&&m.right<=r.width&&m.top>=0&&m.bottom<=r.height,"Match outside image");for(ChartEngine.Point p:m.points)check(Float.isFinite(p.x)&&Float.isFinite(p.y)&&p.x>=0&&p.x<=r.width&&p.y>=0&&p.y<=r.height,"Invalid outline");}}
    public static void localizesKnownPeaks(){ChartEngine.Result r=sample(false,false);ChartEngine.Match m=r.matches.get(0);check(m.first==13&&m.last==34,"Expected known peak candle indices");check(Math.abs(m.points.get(0).x-(60+13*19+5))<1,"First peak localization incorrect");check(Math.abs(m.points.get(2).x-(60+34*19+5))<1,"Second peak localization incorrect");}
    public static void cancellationBeforePixels(){AtomicInteger count=new AtomicInteger();boolean rejected=false;try{new ChartEngine().analyze(400,200,new int[80000],()->{count.incrementAndGet();throw new CancellationException();});}catch(CancellationException e){rejected=true;}check(rejected&&count.get()==1,"Cancellation swallowed");}
    public static void cancellationDuringPixels(){AtomicInteger count=new AtomicInteger();boolean rejected=false;try{new ChartEngine().analyze(SamplePixels.WIDTH,SamplePixels.HEIGHT,SamplePixels.create(false,false),()->{if(count.incrementAndGet()==10)throw new CancellationException();});}catch(CancellationException e){rejected=true;}check(rejected&&count.get()==10,"Image loop is not cancelable");}
    private static List<ChartEngine.Candle> series(int... ys){ArrayList<ChartEngine.Candle> list=new ArrayList<>();for(int i=0;i<ys.length;i++)list.add(new ChartEngine.Candle(10+i*12,18+i*12,ys[i]-13,ys[i]+13,ys[i]-5,ys[i]+5,i%2==0));return list;}
    private static List<ChartEngine.Match> recognize(List<ChartEngine.Candle> c){return new ChartEngine().recognize(c,()->{});}
    public static void doubleBottom(){List<ChartEngine.Candle> c=series(100,120,150,180,210,230,200,160,130,110,130,160,200,228,200,160,120);check(has(recognize(c),"double_bottom"),"Known double bottom not recognized");}
    public static void headShoulders(){List<ChartEngine.Candle> c=series(270,220,180,140,170,210,230,180,130,80,100,160,210,230,200,170,145,180,220,270);check(has(recognize(c),"head_shoulders"),"Known head-and-shoulders not recognized");}
    public static void inverseHeadShoulders(){List<ChartEngine.Candle> c=series(80,130,170,210,180,140,120,170,220,270,250,190,140,120,150,180,205,170,130,80);check(has(recognize(c),"inverse_head_shoulders"),"Known inverse head-and-shoulders not recognized");}
    public static void trendIsNotDoubleTop(){check(!has(recognize(series(300,280,260,240,220,200,180,160,140,120,100)),"double_top"),"Monotonic trend became a double top");}
    public static void doji(){List<ChartEngine.Candle> c=series(200,190,180,170,160,150,140,130);c.set(7,new ChartEngine.Candle(94,102,90,160,125,128,true));check(has(recognize(c),"doji"),"Doji not recognized");}
    public static void engulfing(){List<ChartEngine.Candle> c=series(200,190,180,170,160,150,140,130);c.set(6,new ChartEngine.Candle(82,90,112,152,128,142,false));c.set(7,new ChartEngine.Candle(94,102,100,165,115,154,true));check(has(recognize(c),"bullish_engulfing"),"Engulfing body not recognized");}
    public static void invalidCandleRejected(){boolean rejected=false;try{new ChartEngine.Candle(20,10,0,10,2,8,true);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"Inverted candle accepted");}
    public static void observationsImmutable(){ChartEngine.Result r=sample(false,false);boolean immutable=false;try{r.candles.clear();}catch(UnsupportedOperationException e){immutable=true;}check(immutable,"Caller can mutate saved measurements");}
    public static void lowerWick(){List<ChartEngine.Candle> c=series(200,190,180,170,160,150,140,130);c.set(7,new ChartEngine.Candle(94,102,120,160,124,134,true));check(has(recognize(c),"hammer"),"Long lower wick not recognized");}
    public static void upperWick(){List<ChartEngine.Candle> c=series(200,190,180,170,160,150,140,130);c.set(7,new ChartEngine.Candle(94,102,100,140,126,136,false));check(has(recognize(c),"shooting_star"),"Long upper wick not recognized");}
    public static void bearishEngulfing(){List<ChartEngine.Candle> c=series(200,190,180,170,160,150,140,130);c.set(6,new ChartEngine.Candle(82,90,112,152,128,142,true));c.set(7,new ChartEngine.Candle(94,102,100,165,115,154,false));check(has(recognize(c),"bearish_engulfing"),"Bearish engulfing not recognized");}
    public static void ascendingTriangle(){check(has(recognize(series(300,260,220,180,140,180,230,280,240,200,142,190,230,240,220,180,141,190,240)),"ascending_triangle"),"Ascending triangle not recognized");}
    public static void descendingTriangle(){int[] values={300,260,220,180,140,180,230,280,240,200,142,190,230,240,220,180,141,190,240};for(int i=0;i<values.length;i++)values[i]=440-values[i];check(has(recognize(series(values)),"descending_triangle"),"Descending triangle not recognized");}
    public static void symmetricalTriangle(){check(has(recognize(series(300,240,180,130,180,250,300,250,200,160,200,240,270,230,180,205,245)),"symmetrical_triangle"),"Symmetrical triangle not recognized");}
    private static int[] scale(int[] source,int sw,int sh,int w,int h){int[] out=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){float fx=(x+.5f)*sw/w-.5f,fy=(y+.5f)*sh/h-.5f;int x0=Math.max(0,Math.min(sw-1,(int)Math.floor(fx))),y0=Math.max(0,Math.min(sh-1,(int)Math.floor(fy)));int x1=Math.min(sw-1,x0+1),y1=Math.min(sh-1,y0+1);float a=Math.max(0,fx-x0),b=Math.max(0,fy-y0);int value=0xff000000;for(int shift=0;shift<=16;shift+=8){float top=((source[y0*sw+x0]>>shift)&255)*(1-a)+((source[y0*sw+x1]>>shift)&255)*a;float bottom=((source[y1*sw+x0]>>shift)&255)*(1-a)+((source[y1*sw+x1]>>shift)&255)*a;value|=Math.round(top*(1-b)+bottom*b)<<shift;}out[y*w+x]=value;}return out;}
    public static void scaledGrayScreen(){int[] chart=scale(SamplePixels.create(false,true),960,540,1040,585),screen=new int[1080*1920];Arrays.fill(screen,0xff080e19);for(int y=0;y<585;y++)System.arraycopy(chart,y*1040,screen,(736+y)*1080+20,1040);int[] captured=scale(screen,1080,1920,900,1600);ChartEngine.Result r=new ChartEngine().analyze(900,1600,captured);check(r.candles.size()==44,"Screen resampling lost candles: "+r.candles.size());check(has(r.matches,"double_top"),"Resampled chart structure lost");}
    private static ChartEngine.Result hollow(boolean light){ChartEngine.Result original=sample(light,false);int[] px=SamplePixels.create(light,false);int bg=px[0];for(ChartEngine.Candle c:original.candles)for(int y=c.bodyTop+1;y<c.bodyBottom-1;y++)for(int x=c.left+1;x<c.right-1;x++)px[y*SamplePixels.WIDTH+x]=bg;return new ChartEngine().analyze(SamplePixels.WIDTH,SamplePixels.HEIGHT,px);}
    public static void hollowDark(){ChartEngine.Result r=hollow(false);check(r.readable()&&r.candles.size()==44,"Dark outlined bodies were dropped");check(has(r.matches,"double_top"),"Outlined chart structure lost");}
    public static void hollowLight(){ChartEngine.Result r=hollow(true);check(r.readable()&&r.candles.size()==44,"Light outlined bodies were dropped");}
    private static void rectangle(int[] px,int w,int l,int t,int r,int b,int color){for(int y=t;y<b;y++)for(int x=l;x<r;x++)px[y*w+x]=color;}
    public static void shortWideCandles(){int w=480,h=220;int[] px=new int[w*h];Arrays.fill(px,0xff111820);for(int i=0;i<24;i++){int x=30+i*17,y=60+(i%6)*15,color=i%2==0?0xff42ddb2:0xffef7d85;rectangle(px,w,x+4,y-3,x+6,y+6,color);rectangle(px,w,x,y,x+10,y+3,color);}ChartEngine.Result r=new ChartEngine().analyze(w,h,px);check(r.readable()&&r.candles.size()==24,"Short wide candles rejected: "+r.candles.size());}
    public static void neutralOutlinedBody(){int[] px=SamplePixels.create(true,true);ChartEngine.Candle body=sample(true,true).candles.get(12);int ink=0xff222222;rectangle(px,960,body.left-1,body.bodyTop-1,body.right+1,body.bodyTop,ink);rectangle(px,960,body.left-1,body.bodyBottom,body.right+1,body.bodyBottom+1,ink);rectangle(px,960,body.left-1,body.bodyTop,body.left,body.bodyBottom,ink);rectangle(px,960,body.right,body.bodyTop,body.right+1,body.bodyBottom,ink);ChartEngine.Result r=new ChartEngine().analyze(960,540,px);check(r.readable()&&r.candles.size()==44,"Neutral outline lost its candle");check(r.candles.get(12).top<=body.top&&r.candles.get(12).bottom>=body.bottom,"Neutral border truncated its wick");}
    public static void labelClustersRejected(){int[] px=new int[640*240];Arrays.fill(px,0xfffafafa);for(int i=0;i<12;i++){int x=15+(i%6)*15+(i/6)*430,y=40+(i%3)*16;rectangle(px,640,x,y,x+8,y+3,0xffdf3333);rectangle(px,640,x+3,y,x+5,y+20,0xffdf3333);}check(!new ChartEngine().analyze(640,240,px).readable(),"Disjoint label fragments accepted as a price series");}
    public static void olderVisibleCandle(){List<ChartEngine.Candle> c=series(200,190,180,170,160,150,140,130,120,110,100,90);c.set(1,new ChartEngine.Candle(22,30,170,215,173,185,true));check(has(recognize(c),"hammer"),"Older visible wick was silently ignored");}
    public static int[] tracePixels(){int w=640,h=300;int[] px=new int[w*h];Arrays.fill(px,0xfffafafa);int[] xs={20,160,315,480,620},ys={245,60,220,62,245};for(int segment=1;segment<xs.length;segment++)for(int x=xs[segment-1];x<=xs[segment];x++){int y=Math.round(ys[segment-1]+(ys[segment]-ys[segment-1])*(x-xs[segment-1])/(float)(xs[segment]-xs[segment-1]));rectangle(px,w,x,y-1,x+1,y+2,0xff223333);}return px;}
    public static void traceDoubleTop(){ChartEngine.Result r=new ChartEngine().analyzeTrace(640,300,tracePixels());check(r.readable(),r.problem);check(r.candles.isEmpty()&&"trace".equals(r.inputType),"Trace invented candle observations");check(has(r.matches,"double_top"),"Known line structure missed");for(ChartEngine.Match m:r.matches)check(!"Candle".equals(m.family),"Trace generated a candle formation");for(ChartEngine.Point p:r.tracePoints)check(p.top<=p.y&&p.y<=p.bottom&&p.bottom<300,"Trace left observed bounds");}
    public static void traceBlankRejected(){int[] px=new int[640*300];Arrays.fill(px,0xffeeeeee);check(!new ChartEngine().analyzeTrace(640,300,px).readable(),"Blank trace accepted");}
    public static void traceNoiseRejected(){int[] px=new int[640*300];Random random=new Random(42);for(int i=0;i<px.length;i++)px[i]=0xff000000|random.nextInt(0x1000000);check(!new ChartEngine().analyzeTrace(640,300,px).readable(),"Noise became a trace");}
    public static void traceCancellation(){boolean stopped=false;try{new ChartEngine().analyzeTrace(640,300,tracePixels(),()->{throw new CancellationException();});}catch(CancellationException e){stopped=true;}check(stopped,"Trace ignored cancellation");}
    public static void traceObservationsImmutable(){ChartEngine.Result r=new ChartEngine().analyzeTrace(640,300,tracePixels());boolean immutable=false;try{r.tracePoints.clear();}catch(UnsupportedOperationException e){immutable=true;}check(immutable,"Trace can be changed by a caller");}
    public static void main(String[] args) throws Exception {
        String[] names={"darkChart","lightChart","darkNeutralWicks","lightNeutralWicks","blankRejected","tooSmallRejected","badDimensions","transparentRejected","unsupportedPalette","noiseRejected","volumeRejected","measuredBodies","boundsRemainInImage","localizesKnownPeaks","cancellationBeforePixels","cancellationDuringPixels","doubleBottom","headShoulders","inverseHeadShoulders","trendIsNotDoubleTop","doji","engulfing","invalidCandleRejected","observationsImmutable","lowerWick","upperWick","bearishEngulfing","ascendingTriangle","descendingTriangle","symmetricalTriangle","scaledGrayScreen","hollowDark","hollowLight","shortWideCandles","neutralOutlinedBody","labelClustersRejected","olderVisibleCandle","traceDoubleTop","traceBlankRejected","traceNoiseRejected","traceCancellation","traceObservationsImmutable"};
        int passed=0;for(String name:names){try{EngineChecks.class.getMethod(name).invoke(null);passed++;System.out.println("PASS "+name);}catch(java.lang.reflect.InvocationTargetException e){throw new AssertionError(name+": "+e.getCause(),e.getCause());}}
        System.out.println("Passed "+passed+" core regressions");
    }
}
